import * as alien from "@alienplatform/core"

const uploads = new alien.Storage("uploads").build()
const sessions = new alien.Kv("sessions").build()
const jobs = new alien.Queue("jobs").build()
const secrets = new alien.Vault("secrets").build()

const database = new alien.Container("database")
  .code({ type: "image", image: "ghcr.io/acme/database:1.0.0" })
  .cpu(2)
  .memory("4Gi")
  .port(5432)
  .permissions("database")
  .build()

const api = new alien.Container("api")
  .code({ type: "image", image: "ghcr.io/acme/api:1.0.0" })
  .cpu(1)
  .memory("1Gi")
  .link(secrets)
  .link(uploads)
  .link(database)
  .link(jobs)
  .link(sessions)
  .permissions("api")
  .build()

export default new alien.Stack("acme-links")
  .platforms(["aws", "gcp", "azure"])
  .add(uploads, "frozen")
  .add(sessions, "frozen")
  .add(jobs, "frozen")
  .add(secrets, "frozen")
  .add(api, "live")
  .add(database, "live")
  .permissions({ profiles: { api: {}, database: {} } })
  .build()
